using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.Http;
using System.Net.Sockets;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Threading;
namespace AkilliKisayol {
 public static class ModelCompatibilityTests {
  static string Plan(string steps){return "{\"trigger\":\"F8\",\"steps\":"+steps+"}";}
  static string Envelope(object message,string finish){return LocalLlm.Json().Serialize(new{choices=new[]{new{finish_reason=finish,message=message}}});}
  static bool Reject(Action action){try{action();return false;}catch(Exception){return true;}}
  public static void Unit(Action<bool,string> check){
   string copy=Plan("[{\"kind\":\"copy\"}]");var request=new LlmRequest{Prompt="When I press F8, copy the selected text.",Applications=new List<string>(),Options=new ModelOptions()};
   check(LlmProtocol.ReadPlan(copy,request).Ready,"Optional unused JSON fields are normalized without inventing actions");
   check(LlmProtocol.ReadPlan("Here is the plan:\n```json\n"+copy+"\n```",request).Ready,"One balanced JSON plan can be extracted from surrounding prose");
   check(Reject(()=>LlmProtocol.ReadPlan(copy+copy,request))&&Reject(()=>LlmProtocol.ReadPlan("<think>unfinished "+copy,request)),"Multiple alternatives and unfinished reasoning cannot become executable plans");
   check(ModelWire.Completion(Envelope(new{content=new[]{new{type="output_text",text=copy}}},"stop"))==copy,"Content block completion dialect is accepted");
   check(ModelWire.Completion(Envelope(new{content=(string)null,tool_calls=new[]{new{function=new{name="plan",arguments=copy}}}},"tool_calls"))==copy,"Single structured plan tool call is accepted and still validated");
   check(ModelWire.Completion(Envelope(new{function_call=new{name="plan",arguments=copy}},"function_call"))==copy,"Legacy function call completion dialect is accepted");
   check(Reject(()=>ModelWire.Completion(Envelope(new{content=copy},"length")))&&Reject(()=>ModelWire.Completion(Envelope(new{reasoning_content=copy},"stop"))),"Truncated responses and reasoning-only responses are rejected");
   check(Reject(()=>ModelWire.Completion(Envelope(new{tool_calls=new[]{new{function=new{arguments=copy}},new{function=new{arguments=copy}}}},"tool_calls"))),"Multiple plan tool calls are rejected");
   check(Reject(()=>LlmProtocol.ReadPlan(Plan("[{\"kind\":\"select_all\"},{\"kind\":\"copy\"}]"),request)),"Selected-text copy cannot silently expand the selection");
   request.Prompt="When I press F8, type \"Hello\", wait 100 ms, then press Enter.";
   string correct=Plan("[{\"kind\":\"text\",\"text\":\"Hello\"},{\"kind\":\"wait\",\"ms\":\"100\"},{\"kind\":\"key\",\"combo\":\"Enter\"}]");
   check(LlmProtocol.ReadPlan(correct,request).Ready&&LlmProtocol.ReadPlan(correct.Replace("\"100\"","100.0"),request).Ready,"Integral numeric string and decimal wait values preserve their exact duration");
   check(Reject(()=>LlmProtocol.ReadPlan(correct.Replace("\"100\"","1000"),request))&&Reject(()=>LlmProtocol.ReadPlan(correct.Replace("\"Hello\"","\"Changed\""),request)),"Explicit text and wait changes trigger correction instead of a ready preview");
   check(Reject(()=>LlmProtocol.ReadPlan(Plan("[{\"kind\":\"key\",\"combo\":\"Enter\"},{\"kind\":\"wait\",\"ms\":100},{\"kind\":\"text\",\"text\":\"Hello\"}]"),request)),"Reversed literal text action order is rejected");
   check(Reject(()=>LlmProtocol.ReadPlan(correct.Replace("\"100\"","0.5"),request))&&Reject(()=>LlmProtocol.ReadPlan(Plan("[{\"kind\":\"wait\"}]"),request)),"Fractional and missing wait durations are not guessed");
   request.Prompt="Copy the selected text.";
   check(!LlmProtocol.ReadPlan("{\"status\":\"clarify\",\"message\":\"Which key?\",\"steps\":[{\"kind\":\"copy\"}]}",request).Ready,"Questions discard non-executable suggested actions and remain clarification");
   request.Prompt="When I press F8, copy the selected text.";check(Reject(()=>LlmProtocol.ReadPlan(copy.Substring(0,copy.Length-1)+",\"code\":\"unexpected\"}",request))&&Reject(()=>LlmProtocol.ReadPlan(Plan("[{\"kind\":\"unknown_action\"}]"),request)),"Unknown root fields and unsupported action names remain rejected");
   var options=new ModelOptions{Endpoint="http://localhost:1234/v1/chat/completions",MaxOutputTokens=0};check(options.BaseUri().AbsoluteUri=="http://localhost:1234/v1/"&&options.TokenBudget==2048,"Full completion URLs and legacy token settings are compatible");
   using(var content=new StringContent(new string('x',131073)))check(Reject(()=>ModelTransport.ReadBody(content,CancellationToken.None).GetAwaiter().GetResult()),"Oversized model response is bounded before parsing");
   Server(check,false);Server(check,true);StalledBody(check);
  }
  static void StalledBody(Action<bool,string> check){var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();int port=((IPEndPoint)listener.LocalEndpoint).Port;var server=Task.Run(()=>{using(var client=listener.AcceptTcpClient()){client.ReceiveTimeout=5000;using(var stream=client.GetStream()){string header="";while(!header.EndsWith("\r\n\r\n")){int value=stream.ReadByte();if(value<0)throw new IOException("Fixture disconnected");header+=(char)value;}byte[] head=Encoding.ASCII.GetBytes("HTTP/1.1 200 OK\r\nContent-Length: 10000\r\n\r\n");stream.Write(head,0,head.Length);stream.ReadByte();}}});try{using(var client=new HttpClient(new HttpClientHandler{UseProxy=false}))using(var timeout=new CancellationTokenSource(500))using(var response=client.GetAsync("http://127.0.0.1:"+port+"/",HttpCompletionOption.ResponseHeadersRead).GetAwaiter().GetResult()){bool cancelled=false;try{ModelTransport.ReadBody(response.Content,timeout.Token).GetAwaiter().GetResult();}catch(OperationCanceledException){cancelled=true;}check(cancelled,"Cancellation interrupts a server that sends headers but stalls its response body");}server.GetAwaiter().GetResult();}finally{listener.Stop();}}
  static void Server(Action<bool,string> check,bool unauthorized){
   var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();int port=((IPEndPoint)listener.LocalEndpoint).Port;var requests=new List<Dictionary<string,object>>();
   var server=Task.Run(()=>{int count=unauthorized?1:6;for(int i=0;i<count;i++)using(var client=listener.AcceptTcpClient()){client.ReceiveTimeout=5000;client.SendTimeout=5000;using(var stream=client.GetStream()){var header=new StringBuilder();while(!header.ToString().EndsWith("\r\n\r\n")){int b=stream.ReadByte();if(b<0||header.Length>32768)throw new IOException("Invalid fixture request");header.Append((char)b);}string headers=header.ToString();int length=int.Parse(headers.Split(new[]{"\r\n"},StringSplitOptions.None).First(x=>x.StartsWith("Content-Length:",StringComparison.OrdinalIgnoreCase)).Split(':')[1]);if(headers.IndexOf("100-continue",StringComparison.OrdinalIgnoreCase)>=0){byte[] interim=Encoding.ASCII.GetBytes("HTTP/1.1 100 Continue\r\n\r\n");stream.Write(interim,0,interim.Length);}var bytes=new byte[length];for(int offset=0;offset<length;){int read=stream.Read(bytes,offset,length-offset);if(read==0)throw new IOException("Incomplete fixture body");offset+=read;}requests.Add((Dictionary<string,object>)LocalLlm.Json().DeserializeObject(Encoding.UTF8.GetString(bytes)));string body=unauthorized?"Unauthorized":i==0?"Unsupported response_format type json_schema; use json_object":i==1?"Unsupported parameter response_format":i==2?"Use max_completion_tokens instead of max_tokens":i==3?"Unsupported temperature; only the default is supported":Envelope(new{content=Plan("[{\"kind\":\"copy\"}]")},"stop");int status=unauthorized?401:i<4?400:200;bytes=Encoding.UTF8.GetBytes(body);byte[] head=Encoding.ASCII.GetBytes("HTTP/1.1 "+status+" Fixture\r\nContent-Type: application/json\r\nContent-Length: "+bytes.Length+"\r\nConnection: close\r\n\r\n");stream.Write(head,0,head.Length);stream.Write(bytes,0,bytes.Length);}}});
   try{using(var transport=new ModelTransport())using(var timeout=new CancellationTokenSource(15000)){var options=new ModelOptions{Remote=true,Model="fixture",Endpoint="http://127.0.0.1:"+port+"/v1/"};var payload=new Dictionary<string,object>{{"model","fixture"},{"response_format",new{type="json_schema"}},{"temperature",0},{"max_tokens",2048}};if(unauthorized)check(Reject(()=>transport.Complete(options,payload,p=>{},timeout.Token).GetAwaiter().GetResult()),"Authentication failures surface without generation retries");else{transport.Complete(options,payload,p=>{},timeout.Token).GetAwaiter().GetResult();transport.Complete(options,payload,p=>{},timeout.Token).GetAwaiter().GetResult();}server.GetAwaiter().GetResult();check(unauthorized?requests.Count==1:requests.Count==6&&((Dictionary<string,object>)requests[1]["response_format"])["type"].Equals("json_object")&&!requests[5].ContainsKey("response_format")&&!requests[5].ContainsKey("temperature")&&!requests[5].ContainsKey("max_tokens")&&requests[5].ContainsKey("max_completion_tokens"),unauthorized?"HTTP 401 is sent only once":"Actual HTTP capability negotiation is cached for subsequent prompts");}}finally{listener.Stop();}
  }
  public static void Ui(Action<bool,string> check){var samples=new List<double>();using(var engine=new KeyboardEngine()){int fires=0;var shortcut=new Binding{Key=119,Kind="Send key",SendKey=67,SendMods=2};engine.Bindings=()=>new List<Binding>{shortcut};engine.Fire=(b,w)=>fires++;for(int i=0;i<100;i++){engine.Handle(new Native.Keyboard{vk=119});check(fires==i,"Activation is not dispatched while its key is held");long start=Stopwatch.GetTimestamp();engine.Handle(new Native.Keyboard{vk=119,flags=0x80});Application.Current.Dispatcher.Invoke(DispatcherPriority.Input,new Action(()=>{}));samples.Add((Stopwatch.GetTimestamp()-start)*1000.0/Stopwatch.Frequency);check(fires==i+1,"Released shortcut dispatches in the next input queue turn without polling delay");}}samples.Sort();File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"input-dispatch-timing.json"),LocalLlm.Json().Serialize(new{samples=samples.Count,medianMilliseconds=samples[50],p95Milliseconds=samples[95],maximumMilliseconds=samples[99],scope="Synthetic key release through native engine and WPF input queue, callback only; excludes OS app startup and macro action duration"}));}
 }
}
